function PARTITION(A, p, r) {
  const x = pivot(r);
  let i = p - 1;
  setI(i);

  for (let j = p; j <= r - 1; j++) {
    setJ(j);
    note('Before the test, A[p..i] <= x, A[i+1..j-1] > x, and A[j..r-1] is unrestricted.');

    if (compare(j, x)) {
      i = i + 1;
      swap(i, j);
      setI(i);
      note('A[j] belongs in the <= x region, so expand that region and swap it in.');
    } else {
      note('A[j] belongs in the > x region, so leave it where it is.');
    }
  }

  swap(i + 1, r);
  setI(i + 1);
  note('The pivot is placed between the final <= x and > x regions.');
  return i + 1;
}

